  }
  if (options.protocol) {
    t.assert.ok(req.protocol, 'protocol is defined')
    t.assert.strictEqual(req.protocol, options.protocol, 'gets protocol from x-forwarded-proto')
  }
  if ('port' in options) {
    t.assert.strictEqual(req.port, options.port, 'port is derived from host')
  }
}

